/**
 * Offline shell for Fitness Track.
 *
 * The app is used in gym basements with no signal, and all of its data already
 * lives in localStorage — so the only thing standing between it and working
 * offline is the shell itself. There is no sync, no API, and nothing to
 * reconcile: cache the files, and the app works.
 *
 * Deliberately hand-rolled rather than generated by Workbox. A Workbox
 * precache manifest lists EVERY build asset, including the 1.2 MB lazy
 * exercise-library chunk that CLAUDE.md and the handoff both say must stay
 * lazy, so it would pull the whole library down on first visit.
 *
 * Instead, install fetches the built index.html and precaches the assets it
 * references, plus the lazy ROUTE chunks named in the JSON block that
 * vite-plugin-sw-precache.ts injects into it. That block lists each route
 * chunk and its STATIC imports only, so the 1.2 MB library — a dynamic import
 * of a route chunk — is absent by construction rather than by an exclusion
 * list that could go stale. Routes have to be in there: they are dynamic
 * imports too, so the attribute scan cannot see them, and a route you had
 * never opened online would 503 offline.
 *
 * Precaching (rather than caching as requests fly by) is what makes the FIRST
 * online visit enough. A worker does not control the page that registers it
 * until it activates, by which point the app's own assets have already been
 * fetched past it — so a purely runtime-cached app stays broken offline until
 * its second visit. Verified in a real browser: without this, an offline
 * reload after one visit renders a blank page.
 *
 * Strategies:
 * - navigations  → network-first, falling back to the cached shell. Keeps
 *   deploys landing immediately when online, and deep links working offline
 *   (the router resolves the path once the shell boots).
 * - same-origin assets → cache-first. Vite content-hashes filenames, so a
 *   cached asset can never be stale; a changed file is a different URL.
 * - cross-origin → untouched. The hotlinked demo images stay on the network.
 *   Fonts USED to be here: they came from fonts.googleapis.com, and because a
 *   worker must not touch cross-origin requests it could do nothing about it —
 *   the app rendered in fallback fonts offline (handoff gap #7, now fixed).
 *   They are self-hosted and precached below, so they work on the first
 *   offline visit rather than the second.
 *
 * Bump VERSION to evict everything; `activate` deletes any cache that is not
 * the current one. There is no skipWaiting, so a new worker takes over once
 * the app is fully closed rather than swapping assets under a live page.
 */
/* v3: lazy route chunks joined the precache, so the v2 cache is incomplete. */
const VERSION = 'v3';
const CACHE = `fitness-track-${VERSION}`;

/** Scope root, e.g. "/Fitness-track/" — derived so no path is hardcoded. */
const BASE = new URL('./', self.location.href).pathname;

const STATIC_SHELL = [
  `${BASE}manifest.webmanifest`,
  `${BASE}icons/icon-192.png`,
  `${BASE}icons/icon-512.png`,
  `${BASE}icons/apple-touch-icon.png`,
  /*
   * Listed by name, which only works because these live in public/ and are
   * copied verbatim — an unhashed filename is the point. The scan below reads
   * hashed asset URLs out of the shell HTML, but the woff2 URLs appear inside
   * fonts.css rather than the HTML, so nothing would find them there.
   */
  `${BASE}fonts/fonts.css`,
  `${BASE}fonts/dm-sans-latin.woff2`,
  `${BASE}fonts/space-grotesk-latin.woff2`,
];

/**
 * The lazy ROUTE chunks, read out of the JSON block that
 * vite-plugin-sw-precache.ts injects into the shell.
 *
 * Routes are lazy, so their chunks are dynamic imports and appear nowhere in
 * the HTML's src/href attributes — the scan below cannot see them. Left at
 * that they would fall to cacheFirst and 503 for a route never opened ONLINE,
 * which is the offline guarantee this worker exists to provide.
 *
 * The block lists each route chunk and its STATIC imports only, so the 1.2 MB
 * exercise library (a dynamic import of a route chunk) is absent by
 * construction rather than by an exclusion list that could go stale.
 *
 * Reading it costs nothing at first paint: the browser ignores a JSON script
 * tag, so these are fetched by the worker during install, not by the page.
 */
function routeChunks(html) {
  const match = html.match(
    /<script[^>]*id="sw-precache"[^>]*>([\s\S]*?)<\/script>/,
  );
  if (!match) return [];
  try {
    const files = JSON.parse(match[1]);
    return Array.isArray(files) ? files.map((f) => `${BASE}${f}`) : [];
  } catch {
    // A malformed block must not fail the install; the shell still caches.
    return [];
  }
}

/**
 * The hashed first-paint assets, read out of the shell HTML. Filenames change
 * every build, so they cannot be listed here; the HTML is the one place that
 * always names the current set. The data: URI favicon parses to a null origin
 * and drops out of the same-origin filter.
 */
function firstPaintAssets(html) {
  const urls = new Set();
  for (const [, href] of html.matchAll(/(?:src|href)="([^"]+)"/g)) {
    let url;
    try {
      url = new URL(href, self.location.href);
    } catch {
      continue;
    }
    if (url.origin === self.location.origin && url.pathname.startsWith(`${BASE}assets/`)) {
      urls.add(url.pathname);
    }
  }
  return [...urls];
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // 'reload' so a redeploy cannot precache the previous HTTP-cached shell.
      const shell = await fetch(BASE, { cache: 'reload' });
      if (shell.ok) {
        const html = await shell.clone().text();
        await cache.put(BASE, shell);
        const assets = new Set([...firstPaintAssets(html), ...routeChunks(html)]);
        await Promise.all([...assets].map((url) => cache.add(url).catch(() => undefined)));
      }
      // Individually, so one missing icon cannot fail the whole install.
      await Promise.all(STATIC_SHELL.map((url) => cache.add(url).catch(() => undefined)));
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(names.filter((n) => n !== CACHE).map((n) => caches.delete(n)));
      await self.clients.claim();
    })(),
  );
});

function isCacheable(response) {
  return Boolean(response) && response.ok && response.type === 'basic';
}

/**
 * Assets are content-hashed, so a cached copy can never be wrong — but the
 * server sends `Vary: Origin` and Vite's module script tag carries
 * `crossorigin`, so the page's request has an `Origin` header that the
 * precache request did not. Honouring Vary would make every precached asset
 * invisible to the exact request that needs it, and the app would 503 offline.
 */
const MATCH = { ignoreVary: true };

async function networkFirstShell(request) {
  const cache = await caches.open(CACHE);
  try {
    const fresh = await fetch(request);
    if (isCacheable(fresh)) cache.put(BASE, fresh.clone());
    return fresh;
  } catch {
    const cached = (await cache.match(request, MATCH)) ?? (await cache.match(BASE, MATCH));
    if (cached) return cached;
    return new Response('Offline, and no cached copy of the app is available yet.', {
      status: 503,
      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
    });
  }
}

async function cacheFirst(request) {
  const cache = await caches.open(CACHE);
  const cached = await cache.match(request, MATCH);
  if (cached) return cached;
  try {
    const fresh = await fetch(request);
    if (isCacheable(fresh)) cache.put(request, fresh.clone());
    return fresh;
  } catch {
    // A rejected respondWith surfaces as an opaque network error; a 503 at
    // least tells the caller (e.g. the lazy library import) what happened.
    return new Response('Offline and not cached.', {
      status: 503,
      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
    });
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(networkFirstShell(request));
    return;
  }

  if (!url.pathname.startsWith(BASE)) return;
  event.respondWith(cacheFirst(request));
});
